// Compares the create-ridhuan-backend release on npm with this checkout.
//
//   node scripts/compare-published.mjs [--version 1.7.0] [--local-tarball path.tgz]
//                                      [--template nestjs] [--database mysql] [--keep]
//
// 1. Package: every file of the published tarball must be byte-identical to `npm pack`
//    of this checkout (or --local-tarball), and the file lists must match.
// 2. Generation: each template x database is generated by both packages with the same
//    answers (--yes --no-install). Trees must match file-for-file. Generated secrets differ
//    per run, so .env files are compared by their keys only and the values are never printed.
// Exit code is non-zero when anything differs; a JSON report is written next to the scratch.
import { createHash } from "node:crypto";
import {
  mkdtemp,
  readFile,
  readdir,
  rm,
  writeFile,
  mkdir,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, resolve, sep } from "node:path";
import { spawnSync } from "node:child_process";

const root = resolve(import.meta.dirname, "..");
const argv = process.argv.slice(2);
const option = (name) => {
  const index = argv.indexOf(name);
  return index < 0 ? undefined : argv[index + 1];
};
const pkg = JSON.parse(await readFile(join(root, "package.json"), "utf8"));
const version = option("--version") ?? pkg.version;
const onlyTemplate = option("--template");
const onlyDatabase = option("--database");
const keep = argv.includes("--keep");
const templates = [
  "express-typescript",
  "nestjs",
  "golang",
  "dotnet",
  "fastapi",
  "springboot",
  "laravel",
].filter((id) => !onlyTemplate || id === onlyTemplate);
const databases = ["postgresql", "mysql"].filter(
  (db) => !onlyDatabase || db === onlyDatabase,
);
// Never compared: VCS metadata and anything installed or built after generation.
const skippedDirectories = new Set([
  ".git",
  "node_modules",
  "vendor",
  ".venv",
  "bin",
  "obj",
  "target",
  "dist",
]);
const secretFile = (path) =>
  /(^|\/)\.env(\.[a-z]+)?$/.test(path) && !path.endsWith(".example");

const npm = process.platform === "win32" ? "npm.cmd" : "npm";
function run(executable, args, cwd) {
  const result = spawnSync(executable, args, {
    cwd,
    encoding: "utf8",
    shell: process.platform === "win32" && executable === npm,
    windowsHide: true,
    timeout: 20 * 60 * 1000,
  });
  if (result.status !== 0)
    throw new Error(
      `${executable} ${args.join(" ")} failed (${result.status}): ${(result.stderr || result.stdout).slice(-2000)}`,
    );
  return result.stdout;
}

async function files(directory) {
  const out = new Map();
  async function walk(current) {
    for (const entry of await readdir(current, { withFileTypes: true })) {
      const full = join(current, entry.name);
      if (entry.isDirectory()) {
        if (!skippedDirectories.has(entry.name)) await walk(full);
      } else if (entry.isFile()) {
        out.set(relative(directory, full).split(sep).join("/"), full);
      }
    }
  }
  await walk(directory);
  return out;
}

// `npm pack --json` prints lifecycle (prepack) output before the JSON array.
function packResult(stdout) {
  const start = stdout.search(/^\[/m);
  if (start < 0) throw new Error("npm pack returned no JSON");
  return JSON.parse(stdout.slice(start))[0].filename;
}

const sha = (buffer) => createHash("sha256").update(buffer).digest("hex");
const envKeys = (text) =>
  text
    .split(/\r?\n/)
    .filter((line) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(line))
    .map((line) => line.slice(0, line.indexOf("=")))
    .sort();

async function compareTrees(left, right) {
  const [a, b] = [await files(left), await files(right)];
  const differences = [];
  for (const path of a.keys())
    if (!b.has(path)) differences.push({ path, issue: "only in published" });
  for (const path of b.keys())
    if (!a.has(path)) differences.push({ path, issue: "only in local" });
  for (const [path, full] of a) {
    if (!b.has(path)) continue;
    const [x, y] = [await readFile(full), await readFile(b.get(path))];
    if (secretFile(path)) {
      const [kx, ky] = [
        envKeys(x.toString("utf8")),
        envKeys(y.toString("utf8")),
      ];
      if (kx.join() !== ky.join())
        differences.push({
          path,
          issue: "different .env keys",
          published: kx,
          local: ky,
        });
    } else if (sha(x) !== sha(y)) {
      differences.push({ path, issue: "content differs" });
    }
  }
  return { files: a.size, differences };
}

async function install(tarball, directory) {
  await mkdir(directory, { recursive: true });
  await writeFile(
    join(directory, "package.json"),
    JSON.stringify({ name: "compare-consumer", private: true }),
  );
  run(
    npm,
    ["install", "--no-audit", "--no-fund", "--ignore-scripts", tarball],
    directory,
  );
  return join(
    directory,
    "node_modules",
    "create-ridhuan-backend",
    "dist",
    "bin",
    "index.js",
  );
}

async function extract(tarball, directory) {
  await mkdir(directory, { recursive: true });
  run("tar", ["-xzf", tarball, "-C", directory]);
  return join(directory, "package");
}

const scratch = await mkdtemp(join(tmpdir(), "ridhuan-compare-"));
const report = { version, scratch, package: undefined, generation: [] };
let failed = false;
try {
  // Published tarball, exactly as npm serves it.
  const publishedDir = join(scratch, "published-tarball");
  await mkdir(publishedDir);
  const publishedTarball = join(
    publishedDir,
    packResult(
      run(
        npm,
        [
          "pack",
          `create-ridhuan-backend@${version}`,
          "--json",
          "--pack-destination",
          publishedDir,
        ],
        scratch,
      ),
    ),
  );
  // Local tarball from this checkout (prepack regenerates templates from committed sources).
  let localTarball =
    option("--local-tarball") && resolve(option("--local-tarball"));
  if (!localTarball) {
    const localDir = join(scratch, "local-tarball");
    await mkdir(localDir);
    localTarball = join(
      localDir,
      packResult(
        run(npm, ["pack", "--json", "--pack-destination", localDir], root),
      ),
    );
  }
  console.log(`published: ${publishedTarball}\nlocal:     ${localTarball}`);

  const pkgCompare = await compareTrees(
    await extract(publishedTarball, join(scratch, "x-published")),
    await extract(localTarball, join(scratch, "x-local")),
  );
  report.package = pkgCompare;
  console.log(
    `package: ${pkgCompare.files} files, ${pkgCompare.differences.length} differences`,
  );
  if (pkgCompare.differences.length) failed = true;

  const publishedCli = await install(
    publishedTarball,
    join(scratch, "consumer-published"),
  );
  const localCli = await install(localTarball, join(scratch, "consumer-local"));
  for (const template of templates) {
    for (const database of databases) {
      const name = `cmp-${template}-${database}`;
      const outputs = {};
      for (const [side, cli] of [
        ["published", publishedCli],
        ["local", localCli],
      ]) {
        const cwd = join(scratch, `gen-${side}`);
        await mkdir(cwd, { recursive: true });
        run(
          process.execPath,
          [
            cli,
            name,
            "--template",
            template,
            "--database",
            database,
            "--yes",
            "--no-install",
          ],
          cwd,
        );
        outputs[side] = join(cwd, name);
      }
      const result = await compareTrees(outputs.published, outputs.local);
      report.generation.push({ template, database, ...result });
      const status = result.differences.length ? "DIFF" : "OK";
      if (result.differences.length) failed = true;
      console.log(
        `${status.padEnd(4)} ${template}/${database}: ${result.files} files, ${result.differences.length} differences`,
      );
      for (const difference of result.differences.slice(0, 10))
        console.log(`       ${difference.issue}: ${difference.path}`);
    }
  }
} catch (error) {
  failed = true;
  report.error = String(error instanceof Error ? error.message : error);
  console.error(report.error);
} finally {
  const reportPath = `${scratch}-report.json`;
  await writeFile(reportPath, JSON.stringify(report, null, 2));
  console.log(`report: ${reportPath}`);
  if (!keep) await rm(scratch, { recursive: true, force: true });
  else console.log(`kept: ${scratch}`);
}
console.log(
  failed
    ? "RESULT: DIFFERENCES FOUND"
    : "RESULT: published package and generated projects match this checkout",
);
process.exitCode = failed ? 1 : 0;
